{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Function App public network access is enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not disable public network access, allowing it to be reached through its public endpoint."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Function App does not enable HTTP/2",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App has no site configuration enabling HTTP/2, so it may use an older HTTP protocol version."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Function App authentication is not enabled",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "No authentication settings are enabled on the Function App, leaving application endpoints without platform-level authentication enforcement."
    },
    {
      "check_id": "CKV_AZURE_13",
      "title": "App Service authentication is not configured",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App lacks an enabled App Service authentication configuration, allowing unauthenticated requests unless separately handled by application code."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "MEDIUM",
      "explanation": "The Function App does not set HTTPS-only access, so clients may connect over unencrypted HTTP."
    }
  ],
  "patched_code": "resource \"azurerm_function_app\" \"changeme_simple_function_app\" {\n  name                          = \"changeme-simple-function-app-name\"\n  location                      = azurerm_resource_group.changeme_simple_function_app_resource_group.location\n  resource_group_name           = azurerm_resource_group.changeme_simple_function_app_resource_group.name\n  app_service_plan_id           = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id\n  storage_account_name          = azurerm_storage_account.changeme_simple_function_app_storage_account.name\n  storage_account_access_key    = azurerm_storage_account.changeme_simple_function_app_storage_account.primary_access_key\n  public_network_access_enabled = false\n  https_only                    = true\n\n  site_config {\n    http2_enabled = true\n  }\n\n  auth_settings {\n    enabled = true\n  }\n}\n",
  "fix_summary": "Disabled public network access, enforced HTTPS, enabled HTTP/2, and enabled App Service authentication for the Function App."
}
